-- F0.1: read-only provenance candidate audit for the schema through 00018.
-- Run with psql -X -v ON_ERROR_STOP=1 against an explicitly selected database.
-- These counts do not assign ownership or authorize automatic backfill.
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout = '30s';

SELECT status, count(*) AS runs FROM scenario_runs GROUP BY status ORDER BY status;
SELECT type, count(*) AS sources FROM sources GROUP BY type ORDER BY type;

-- A source type of "sensor" can still be generated by a scenario. Require
-- agreement between the recorded run, explicit metadata, and resource namespace.
-- These are candidates: metadata is not itself an authenticated ownership grant.
WITH resources AS (
    SELECT 'source' AS kind, id AS namespace_ref,
           metadata->>'scenarioRunId' AS claimed_run,
           metadata->>'resourceNamespace' AS claimed_namespace FROM sources
    UNION ALL
    SELECT 'asset', id, metadata->>'scenarioRunId', metadata->>'resourceNamespace' FROM assets
    UNION ALL
    SELECT 'geofence', id, metadata->>'scenarioRunId', metadata->>'resourceNamespace' FROM geofences
    UNION ALL
    SELECT 'track', external_ref, metadata->>'scenarioRunId', metadata->>'resourceNamespace' FROM tracks
    UNION ALL
    SELECT 'observation', id, payload->>'scenarioRunId', payload->>'resourceNamespace' FROM observations
    UNION ALL
    SELECT 'telemetry', message_id, payload->>'scenarioRunId', payload->>'resourceNamespace' FROM asset_telemetry
), candidates AS (
    SELECT kind,
           CASE WHEN r.id IS NOT NULL
                     AND c.claimed_namespace = r.id || '__'
                     AND left(c.namespace_ref, length(r.id || '__' || c.kind || '__')) = r.id || '__' || c.kind || '__'
                THEN 'consistent_run_candidate'
                ELSE 'unresolved_requires_review'
           END AS classification
    FROM resources c LEFT JOIN scenario_runs r ON r.id = c.claimed_run
)
SELECT kind, classification, count(*) AS records
FROM candidates GROUP BY kind, classification ORDER BY kind, classification;

-- Parent relationships must agree even if each row has plausible metadata.
WITH relationships AS (
    SELECT 'observation_source' AS relation,
           o.payload->>'scenarioRunId' AS child_run,
           s.metadata->>'scenarioRunId' AS parent_run
    FROM observations o JOIN sources s ON s.id = o.source_id
    UNION ALL
    SELECT 'telemetry_asset', t.payload->>'scenarioRunId', a.metadata->>'scenarioRunId'
    FROM asset_telemetry t JOIN assets a ON a.id = t.asset_id
    UNION ALL
    SELECT 'track_observation', t.metadata->>'scenarioRunId', o.payload->>'scenarioRunId'
    FROM track_observations x JOIN tracks t ON t.id = x.track_id
    JOIN observations o ON o.id = x.observation_id
    UNION ALL
    SELECT 'track_observation_source', o.payload->>'scenarioRunId', s.metadata->>'scenarioRunId'
    FROM track_observations x JOIN observations o ON o.id = x.observation_id
    JOIN sources s ON s.id = x.source_id
    UNION ALL
    SELECT 'geofence_track', t.metadata->>'scenarioRunId', g.metadata->>'scenarioRunId'
    FROM geofence_states x JOIN tracks t ON t.id = x.track_id
    JOIN geofences g ON g.id = x.geofence_id
)
SELECT relation, count(*) AS relationships,
       count(*) FILTER (WHERE child_run IS NULL OR parent_run IS NULL) AS unresolved,
       count(*) FILTER (WHERE child_run IS NOT NULL AND parent_run IS NOT NULL AND child_run <> parent_run) AS conflicting_run_markers
FROM relationships GROUP BY relation ORDER BY relation;

SELECT count(*) AS audit_records,
       count(*) FILTER (WHERE r.id IS NOT NULL) AS recorded_run_marker,
       count(*) FILTER (WHERE r.id IS NULL) AS no_verified_run_marker
FROM audit_events a LEFT JOIN scenario_runs r ON r.id = a.data->>'scenarioRunId';

SELECT 'alerts' AS aggregate, count(*) AS records FROM alerts
UNION ALL SELECT 'incidents', count(*) FROM incidents
UNION ALL SELECT 'missions', count(*) FROM missions
UNION ALL SELECT 'mission_tasks', count(*) FROM mission_tasks
UNION ALL SELECT 'commands', count(*) FROM commands
UNION ALL SELECT 'classifications', count(*) FROM classifications
UNION ALL SELECT 'assessments', count(*) FROM assessments
UNION ALL SELECT 'assessment_evidence', count(*) FROM assessment_evidence
UNION ALL SELECT 'incident_alerts', count(*) FROM incident_alerts
UNION ALL SELECT 'incident_tracks', count(*) FROM incident_tracks
UNION ALL SELECT 'incident_assets', count(*) FROM incident_assets
UNION ALL SELECT 'incident_observations', count(*) FROM incident_observations
UNION ALL SELECT 'incident_assessments', count(*) FROM incident_assessments
UNION ALL SELECT 'mission_assets', count(*) FROM mission_assets
UNION ALL SELECT 'asset_state', count(*) FROM asset_state
UNION ALL SELECT 'track_state', count(*) FROM track_state
UNION ALL SELECT 'track_history', count(*) FROM track_history
UNION ALL SELECT 'operators', count(*) FROM operators
UNION ALL SELECT 'scenario_run_events', count(*) FROM scenario_run_events
ORDER BY aggregate;

COMMIT;
